export const HDF4_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/hdf4-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getHdf4StdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(HDF4_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
